/// </summary>
/// <param name = "_sectionType">NDXBVEmailRequestSectionType</param>
protected void new(NDXBVEmailRequestSectionType _sectionType)
{
    super(_sectionType);

    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, Name1), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, Name1AIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, Name1AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, Name2), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, Name2AIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, Name2AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, Name3), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, Name3AIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, Name3AII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, AddressStreet), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, AddressStreetAIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, AddressStreetAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, AddressZipCode), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, AddressZipCodeAIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, AddressZipCodeAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, AddressCity), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, AddressCityAIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, AddressCityAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, AddressCountryRegionIdISOCode), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, AddressCountryRegionIdISOCodeAIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, AddressCountryRegionIdISOCodeAII));
    this.addFields2Section(fieldNum(NDXBVEMailRequestInstaller, Phone), 
        fieldNum(NDXBVEMailRequestInstallerAIDecisionBasis, PhoneAIDB),
        fieldNum(NDXBVEMailRequestInstallerAIInfo, PhoneAII));
}

/// <summary>
/// PaffH 10.11.25
/// last modified: PaffH 25.11.25
/// </summary>
/// <param name = "_fieldIdAiField">FieldId</param>
/// <param name = "_fieldIdaiFieldDecisionBase">FieldId</param>
/// <param name = "_fieldIdaiFieldInfo">FieldId</param>
private void addFields2Section(FieldId _fieldIdAiField, FieldId _fieldIdaiFieldDecisionBase, FieldId _fieldIdAiFieldInfo)
{
    NDXBVEMailRequestInstaller nDXBVEMailRequestInstaller;
    NDXBVEMailRequestInstallerAIDecisionBasis nDXBVEMailRequestInstallerAIDecisionBasis;
    NDXBVEMailRequestInstallerAIInfo nDXBVEMailRequestInstallerAIInfo;

    NDXBVEmailRequestAIDBFieldContract aiField = NDXBVEmailRequestAIDBFieldContract::constructFromCommon(nDXBVEMailRequestInstaller, _fieldIdAiField);
    NDXBVEmailRequestAIDBFieldDecisionBaseContract aiFieldDecisionBase = NDXBVEmailRequestAIDBFieldDecisionBaseContract::constructFromCommon(nDXBVEMailRequestInstallerAIDecisionBasis, _fieldIdaiFieldDecisionBase);
    NDXBVEmailRequestAIDBFieldInfoContract aiFieldInfo = NDXBVEmailRequestAIDBFieldInfoContract::constructFromCommon(nDXBVEMailRequestInstallerAIInfo, _fieldIdAiFieldInfo);
    sectionGroups.addEnd(NDXBVEmailRequestAIDBSectionGroupContract::construct(aiField, aiFieldDecisionBase, aiFieldInfo));
}

/// <summary>
/// PaffH 10.11.25
